#define LABELED_VERTEX_SET_GRAPH_CORRECT_VERTEX_INSERTION_WITH_LABEL_CORE_RVALUE_LABEL_LVALUE_VERTEX_HANDLE_TEST(TEST_SUITE_NAME,CONCRETE_CLASS_NAME)                                                                                                                                                                                                               \
    TEST(TEST_SUITE,correct_vertex_insertion_with_label__core_rvalue__label_lvalue__vertex_handle) {                                                                                                                                                                                                                                                                \
