        const auto& graph_const_reference = graph;                                                                                                                                                                                                                                                                                                                  \
        ASSERT_EQ(graph.order(),0);                                                                                                                                                                                                                                                                                                                                 \
        ASSERT_EQ(graph_const_reference.order(),0);                                                                                                                                                                                                                                                                                                                 \
        const std::size_t number_of_vertices = 100;                                                                                                                                                                                                                                                                                                                 \
